#!/usr/bin/env bash
# B2 / TD-14 / H-1..H-3 owner simulation (phase 5, Agent 2). READ ONLY: only `aws iam
# simulate-principal-policy`, `aws iam simulate-custom-policy`, `aws iam get-policy` and
# `aws iam get-policy-version`. Nothing is created, changed or deleted, and no secret is read.
#
# Run in AWS CloudShell, eu-central-1, AFTER the bootstrap re-apply of the B2 patch (the deployer
# roles must carry the new policies). The B-cases (boundary) read the boundary policy and
# simulate it as a policy. Every call passes aws:RequestedRegion, which ThisRegionOnly needs
# (G2 finding G2-2). The simulator applies the context keys to every resource of a call, so a
# multi-resource request (an EC2 create: the parent and the new resource) is simulated once per
# resource with that resource's own tags; the request passes only if every line passes.
#
# Expected values come from the local evaluation of the Terraform-rendered policies
# (evidence/02/eval/matrix-result.md). That evaluation is NOT an AWS simulation; this script is.
# Usage: bash b2-owner-simulation.sh | tee b2-owner-simulation.out ; the last line counts mismatches.
set -uo pipefail
export AWS_REGION=eu-central-1 AWS_DEFAULT_REGION=eu-central-1
pass=0; fail=0
check() { # id expected actual description
  if [ "$2" = "$3" ]; then pass=$((pass+1)); echo "PASS $1 $3  $4"; else fail=$((fail+1)); echo "FAIL $1 expected=$2 actual=$3  $4"; fi
}
sim() { # role action resource context...
  local role=$1 action=$2 res=$3; shift 3
  aws iam simulate-principal-policy --policy-source-arn "$role" --action-names "$action" --resource-arns "$res" \
    --context-entries "$1" --query 'EvaluationResults[0].EvalDecision' --output text 2>&1 | tail -1
}
BOUNDARY_NONPROD_ARN=arn:aws:iam::229251310592:policy/munaxa-shared/munaxa-shared-workload-boundary
v=$(aws iam get-policy --policy-arn "$BOUNDARY_NONPROD_ARN" --query Policy.DefaultVersionId --output text)
aws iam get-policy-version --policy-arn "$BOUNDARY_NONPROD_ARN" --version-id "$v" --query PolicyVersion.Document --output json > /tmp/boundary-nonprod.json
simb() { # action resource context...
  local action=$1 res=$2; shift 2
  aws iam simulate-custom-policy --policy-input-list file:///tmp/boundary-nonprod.json --action-names "$action" --resource-arns "$res" \
    --context-entries "$1" --query 'EvaluationResults[0].EvalDecision' --output text 2>&1 | tail -1
}

